"use strict";class SimpleCache{constructor(defaultTTL=3e5){this.cache=new Map;this.defaultTTL=defaultTTL}set(key,value,ttl=this.defaultTTL){const expiresAt=Date.now()+ttl;this.cache.set(key,{value:value,expiresAt:expiresAt});if(Math.random()<.01){this.cleanup()}}get(key){const item=this.cache.get(key);if(!item)return null;if(Date.now()>item.expiresAt){this.cache.delete(key);return null}return item.value}delete(key){return this.cache.delete(key)}clear(){this.cache.clear()}cleanup(){const now=Date.now();for(const[key,item]of this.cache.entries()){if(now>item.expiresAt){this.cache.delete(key)}}}size(){this.cleanup();return this.cache.size}}module.exports=SimpleCache;
